PUZZLE_DIR = os.path.dirname(os.path.abspath(__file__))


def _read_app_version():
    """Return a display version like 'v1.0.0 (22da5e7+)'.

    The base number comes from the VERSION file (bump it by hand on release).
    When the app runs from a git checkout, the short commit hash is appended,
    with '+' if there are uncommitted changes. Hosts without git (e.g. an scp
    deploy) just show the base number.
    """
    import subprocess
    try:
        with open(os.path.join(PUZZLE_DIR, 'VERSION')) as f:
            base = f.read().strip() or '0.0.0'
    except OSError:
        base = '0.0.0'
    label = f'v{base}'
    try:
        sha = subprocess.run(['git', 'rev-parse', '--short', 'HEAD'], cwd=PUZZLE_DIR,
                             capture_output=True, text=True, timeout=2, check=True).stdout.strip()
        dirty = subprocess.run(['git', 'status', '--porcelain', '--untracked-files=no'],
                               cwd=PUZZLE_DIR, capture_output=True, text=True,
                               timeout=2, check=True).stdout.strip()
        if sha:
            label += f' ({sha}{"+" if dirty else ""})'
    except (OSError, subprocess.SubprocessError):
        pass
    return label


APP_VERSION = _read_app_version()


@app.context_processor
def _inject_version():
    # Makes {{ app_version }} available in every template.
    return {'app_version': APP_VERSION}

# --- Password gate (FR-2.1.3) ---
APP_PASSWORD = os.environ.get('FISCHER_PASSWORD', 'fischer')

from functools import wraps
from flask import session, redirect, url_for

def login_required(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        if not session.get('authenticated'):
            # For API calls, return 401; for pages, redirect to login
            if request.path.startswith('/api/'):
                return jsonify({"error": "Authentication required"}), 401
            return redirect(url_for('login_page'))
        return f(*args, **kwargs)
    return decorated

@app.route("/login", methods=["GET", "POST"])
def login_page():
    if request.method == "POST":
        pw = request.form.get("password", "")
        if pw == APP_PASSWORD:
            session['authenticated'] = True
            return redirect(url_for('index'))
        return render_template("login.html", error="Wrong password"), 401
    return render_template("login.html", error=None)

@app.route("/logout")
def logout():
    session.pop('authenticated', None)
    return redirect(url_for('login_page'))

@app.before_request
def require_login():
    # Allow login page and static files without auth
    if request.path in ('/login', '/logout') or request.path.startswith('/static/'):
        return
    if not session.get('authenticated'):
        if request.path.startswith('/api/'):
            return jsonify({"error": "Authentication required"}), 401
        return redirect(url_for('login_page'))


def load_puzzles(pgn_path):
    puzzles = []
    with open(pgn_path) as f:
        while True:
            game = chess.pgn.read_game(f)
            if game is None:
                break
            h = game.headers
            # Get the solution move and comment
            mainline = list(game.mainline())
            solution_san = mainline[0].move if mainline else None
            comment = mainline[0].comment if mainline else ""
            board = chess.Board(h.get("FEN", chess.STARTING_FEN))
            puzzles.append({
                "fen": h.get("FEN", chess.STARTING_FEN),
                "solution_uci": solution_san.uci() if solution_san else "",
                "solution_san": board.san(solution_san) if solution_san else "",
                "comment": comment,
                "white": h.get("White", "?"),
                "black": h.get("Black", "?"),
                "event": h.get("Event", "?"),
                "date": h.get("Date", "?"),
                "reason": h.get("PuzzleReason", ""),
                "move_number": h.get("PuzzleMove", ""),
                "turn": h.get("PuzzleTurn", "white"),
                "acceptable_uci": [x for x in h.get("PuzzleAcceptable", "").split(",") if x],
                "tactics": [x for x in h.get("PuzzleTactics", "").split(",") if x],
            })
    return puzzles


