@app.route("/api/puzzles")
def api_puzzles():
    pgn_file = request.args.get("file", "")
    if not pgn_file or "/" in pgn_file or "\\" in pgn_file:
        return jsonify([])
    path = os.path.join(PUZZLE_DIR, pgn_file)
    if not os.path.isfile(path):
        return jsonify([])
    return jsonify(load_puzzles(path))


@app.route("/api/generate", methods=["POST"])
def api_generate():
    import subprocess
    data = request.get_json()
    pgn_file = data.get("file", "")
    player = data.get("player", "")
    if not pgn_file or "/" in pgn_file or "\\" in pgn_file:
        return jsonify({"error": "Invalid file"}), 400
    path = os.path.join(PUZZLE_DIR, pgn_file)
    if not os.path.isfile(path):
        return jsonify({"error": "File not found"}), 404
    out_name = pgn_file.rsplit(".", 1)[0] + "_puzzles.pgn"
    out_path = os.path.join(PUZZLE_DIR, out_name)
    cmd = ["python", "-u", os.path.join(PUZZLE_DIR, "puzzles.py"), path, "-o", out_path]
    if player:
        cmd += ["-p", player]

    def stream():
        proc = subprocess.Popen(cmd, stdout=subprocess.PIPE, stderr=subprocess.STDOUT, text=True, bufsize=1)
        for line in proc.stdout:
            yield f"data: {line.rstrip()}\n\n"
        proc.wait()
        yield f"data: [DONE:{out_name}]\n\n"

    return app.response_class(stream(), mimetype="text/event-stream")


@app.route("/api/stats/generate", methods=["POST"])
def api_stats_generate():
    """Generate stats for a puzzle PGN file. Classifies tactics and saves per-player."""
    data = request.get_json()
    pgn_file = data.get("file", "")
    player = data.get("player", "")
    if not pgn_file or "/" in pgn_file or "\\" in pgn_file:
        return jsonify({"error": "Invalid file"}), 400
    path = os.path.join(PUZZLE_DIR, pgn_file)
    if not os.path.isfile(path):
        return jsonify({"error": "File not found"}), 404
    results = generate_stats_for_file(path, player_name=player or None)
    return jsonify([{"player": name, "stats": stats, "path": p} for name, stats, p in results])


@app.route("/api/stats/players")
def api_stats_players():
    """List all players with saved stats."""
    if not os.path.isdir(STATS_DIR):
        return jsonify([])
    import json
    players = []
    for f in sorted(os.listdir(STATS_DIR)):
        if f.endswith(".json"):
            with open(os.path.join(STATS_DIR, f)) as fh:
                data = json.load(fh)
                players.append({
                    "file": f,
                    "player": data.get("player", f),
                    "aggregate": data.get("aggregate", {}),
                })
    return jsonify(players)


@app.route("/api/stats/player/<name>")
def api_stats_player(name):
    """Get full stats for a player."""
    import json
    safe = name.replace(" ", "_").lower()
    if ".." in safe or "/" in safe or "\\" in safe:
        return jsonify({"error": "Invalid name"}), 400
    path = os.path.join(STATS_DIR, f"{safe}.json")
    if not os.path.isfile(path):
        return jsonify({"error": "Player not found"}), 404
    with open(path) as f:
        return jsonify(json.load(f))


@app.route("/api/stats/live")
def api_stats_live():
    """Compute stats on-the-fly from a puzzle PGN without saving."""
    pgn_file = request.args.get("file", "")
    player = request.args.get("player", "")
    if not pgn_file or "/" in pgn_file or "\\" in pgn_file:
        return jsonify({"error": "Invalid file"}), 400
    path = os.path.join(PUZZLE_DIR, pgn_file)
    if not os.path.isfile(path):
        return jsonify({"error": "File not found"}), 404
    puzzles = analyze_puzzle_tactics(path)
    if player:
        stats = build_player_stats(puzzles, player)
        return jsonify(stats or {"error": "Player not found in puzzles"})
    # Return stats for all players
    names = set()
    for p in puzzles:
        if p["white"] != "?": names.add(p["white"])
        if p["black"] != "?": names.add(p["black"])
    all_stats = {}
    for name in sorted(names):
        s = build_player_stats(puzzles, name)
        if s:
            all_stats[name] = s
    return jsonify(all_stats)


PROFILE_PATH = os.path.join(PUZZLE_DIR, "active_profile.json")


def get_active_profile():
    import json
    if os.path.isfile(PROFILE_PATH):
        with open(PROFILE_PATH) as f:
            return json.load(f)
    return None


@app.route("/api/profile", methods=["GET"])
def api_profile_get():
    import json
    p = get_active_profile()
    if not p:
        return jsonify({"active": False})
    # Attach saved stats if they exist
    safe = p["name"].replace(" ", "_").lower()
    stats_path = os.path.join(STATS_DIR, f"{safe}.json")
    stats = None
    if os.path.isfile(stats_path):
        with open(stats_path) as f:
            stats = json.load(f)
    return jsonify({"active": True, "name": p["name"], "stats": stats})


@app.route("/api/profile", methods=["POST"])
def api_profile_set():
    import json
    data = request.get_json()
    name = data.get("name", "").strip()
    if not name:
        return jsonify({"error": "Name required"}), 400
    with open(PROFILE_PATH, "w") as f:
        json.dump({"name": name}, f)
    return jsonify({"ok": True, "name": name})


@app.route("/api/profile", methods=["DELETE"])
def api_profile_clear():
    if os.path.isfile(PROFILE_PATH):
        os.remove(PROFILE_PATH)
    return jsonify({"ok": True})


